components.css:
.ds-mission-progress { display: flex; flex-direction: column; gap: var(--space-sm); }
.ds-mission-progress__steps { display: flex; gap: var(--space-sm); margin: 0; padding: 0; list-style: none; }
.ds-mission-progress__steps li { display: grid; place-content: center; flex: 1; min-width: 0; height: 20px; border-radius: var(--radius-badge); background: var(--color-divider); }
.ds-mission-progress__steps .ds-mission-progress__step--done { background: var(--color-lilac-soft); }
.ds-mission-progress__steps .ds-mission-progress__step--correct { background: var(--color-mint); color: var(--color-success); }
.ds-mission-progress__steps .ds-mission-progress__step--wrong { background: var(--color-review-surface); color: var(--color-review-ink); box-shadow: inset 0 0 0 1px var(--color-review-outline); }
.ds-mission-progress__steps .ds-mission-progress__step--unknown { background: var(--color-help-surface); color: var(--color-help-ink); box-shadow: inset 0 0 0 1px var(--color-help-ink); }
.ds-mission-progress__steps .ds-mission-progress__step--current { background: var(--color-focus); }
.ds-mission-progress__steps svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.ds-mission-progress__text { margin: 0; font-size: var(--font-size-label); font-weight: 700; line-height: var(--line-height-label); color: var(--color-ink); }
.ds-mission-progress{font-family:var(--font-family,Nunito,system-ui,sans-serif)}.ds-hidden{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

.ds-report__tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-md);
  margin: 0;
}

.ds-report__tile {
  display: grid;
  grid-template-rows: auto auto 1fr;
  gap: var(--space-sm);
  min-width: 0;
  padding: var(--space-lg);
  border-radius: var(--radius-card);
  background: var(--color-space-raised);
  border: 1px solid var(--color-divider);
}
.ds-report__intro { color: var(--color-ink-muted); font-size: var(--font-size-label); }
.ds-report__tile:first-child { background: var(--color-lilac-soft); border-color: transparent; }
.ds-report__tile:nth-child(2) { background: var(--color-review-surface); border-color: transparent; }
.ds-report__tile:nth-child(3) { background: var(--color-mint-soft); border-color: transparent; }

.ds-report__tile--wide {
  grid-column: 1 / -1;
}

.ds-report__tile-label {

  min-height: calc(2 * var(--font-size-body) * var(--line-height-button));
  font-size: var(--font-size-body);
  font-weight: 900;
  line-height: var(--line-height-button);
  color: var(--color-on-space);
}

.ds-report__tile-value {
  margin: 0;
  font-size: var(--font-size-title);
  font-weight: 900;
  line-height: var(--line-height-title);
  color: var(--color-on-space);
  font-variant-numeric: tabular-nums;
}

.ds-report__tile-note {
  margin: 0;
  align-self: end;
  font-size: var(--font-size-label);
  font-weight: 700;
  line-height: var(--line-height-body);
  color: var(--color-ink-muted);
}
.ds-report__tile:first-child .ds-report__tile-note { color: var(--color-focus); }
.ds-report__tile:nth-child(2) .ds-report__tile-note { color: var(--color-review-ink); }
.ds-report__tile:nth-child(3) .ds-report__tile-note { color: var(--color-success); }
.ds-report__denominator { display: inline-block; font-size: var(--font-size-label); font-weight: 700; line-height: var(--line-height-label); }
.ds-report__level { display: inline-block; padding: var(--space-xs) var(--space-sm); border-radius: var(--radius-badge); background: var(--color-paper); font-weight: 900; }
.ds-report__tile-value--empty { font-size: var(--font-size-body); font-weight: 700; }
.ds-report__tile--wide .ds-report__tile-label { min-height: 0; }
.ds-report__danger-zone { display: grid; padding-top: var(--space-lg); border-top: 1px solid var(--color-divider); }
.ds-report__reset-dialog { width: min(420px, calc(100% - 32px)); max-height: calc(100dvh - 32px); margin: auto; padding: var(--space-xl); overflow: auto; border: 1px solid var(--color-divider); border-radius: var(--radius-card); background: var(--color-paper); color: var(--color-ink); box-shadow: 0 20px 60px rgb(32 39 65 / .24); }
.ds-report__reset-dialog::backdrop { background: rgb(32 39 65 / .48); }
.ds-report__reset-dialog h2 { margin: 0 0 var(--space-md); font-size: var(--font-size-heading-compact); font-weight: 900; line-height: var(--line-height-button); }
.ds-report__reset-dialog p { margin-bottom: var(--space-xl); font-size: var(--font-size-body); hyphens: auto; }
@media (max-width: 360px) { .ds-report__tiles { grid-template-columns: 1fr; } .ds-report__tile-label { min-height: 0; } .ds-report__reset-dialog { padding: var(--space-lg); } }

.ds-report__note {
  display: flex;
  gap: var(--space-md);
  margin: 0;

  color: var(--color-on-space);
  font-size: var(--font-size-label);
}
.ds-report__note svg { flex-shrink: 0; color: var(--color-focus); }
.ds-report__tiles{font-family:var(--font-family,Nunito,system-ui,sans-serif)}
